-- Dataset comments reference Kepmendagri No. 300.2.2-2430 Tahun 2025,
-- cahyadsn/wilayah, and cahyadsn/wilayah_kodepos.
-- Independent structural audit: 83,762 village-level rows, 10,632 distinct
-- five-digit postal codes, no duplicate code, malformed code, blank name,
-- invalid postal code, or orphan district reference.
--
-- Apply after:
--   1. 20260718180000_custom_order_end_to_end_revision.sql
--   2. 20260718181000_indonesia_regions_province_regency_district_seed.sql
--
-- This migration writes only to public.indonesia_regions. It does not create
-- alternate region tables, expose public grants, change RLS, delete, truncate,
-- deactivate, or modify any PIM/Jersey/commerce business record.

begin;

do $preflight$
declare
  district_count integer;
begin
  if to_regclass('public.indonesia_regions') is null then
    raise exception 'Missing public.indonesia_regions; apply the Custom Order migration first';
  end if;

  select count(*) into district_count
  from public.indonesia_regions
  where level = 'district'
    and code ~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{2}$'
    and is_active;

  if district_count < 7285 then
    raise exception 'District catalog incomplete: expected at least 7285 active canonical rows, found %', district_count;
  end if;
end
