do $verification$
declare
  village_count integer;
  invalid_postal_count integer;
begin
  select count(*) into village_count
  from public.indonesia_regions
  where level = 'village'
    and code ~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{2}\.[0-9]{4}$'
    and is_active;

  if village_count < 83762 then
    raise exception 'Village seed verification failed: expected at least 83762 active canonical rows, found %', village_count;
  end if;

  if exists (
    select 1
    from public.indonesia_regions child
    left join public.indonesia_regions parent
      on parent.code = child.parent_code
     and parent.level = 'district'
     and parent.is_active
    where child.level = 'village'
      and child.code ~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{2}\.[0-9]{4}$'
      and child.is_active
      and parent.code is null
  ) then
    raise exception 'Village seed verification failed: orphan canonical district detected';
  end if;

  select count(*) into invalid_postal_count
  from public.indonesia_regions region
  where region.level = 'village'
    and region.code ~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{2}\.[0-9]{4}$'
    and region.is_active
    and (
      cardinality(region.postal_codes) = 0
      or exists (
        select 1
        from unnest(region.postal_codes) postal_code
        where postal_code !~ '^[0-9]{5}$'
      )
    );

  if invalid_postal_count > 0 then
    raise exception 'Village seed verification failed: % rows have missing or malformed postal codes', invalid_postal_count;
  end if;
end
$verification$;

commit;

